ssize_t macvtap_receive(struct macvtap_queue *q, struct msghdr *m,
                        const struct iovec *iv, unsigned long total_len,
                        size_t count, int noblock) {
    struct sk_buff *skb = NULL;
    struct virtio_net_hdr_v1 virt_hdr = {};
    struct virtio_net_hdr *hdr = NULL;
    size_t hdr_len = 0;
    ssize_t ret;

    if (total_len > MACVTAP_MAX_FRAME_SIZE) {
        return -EMSGSIZE;
    }

    if (virtio_legacy_is_needed(q)) {
        hdr_len = sizeof(virt_hdr);
        memcpy(&virt_hdr, m->msg_control, sizeof(virt_hdr));
        hdr = &virt_hdr.hdr;
    }

    skb = alloc_skb(total_len + hdr_len, GFP_KERNEL);
    if (!skb) {
        return -ENOMEM;
    }

    skb_reserve(skb, hdr_len);
    if (copy_from_iter(skb->data, total_len, m->msg_iter) != total_len) {
        kfree_skb(skb);
        return -EFAULT;
    }

    skb_put(skb, total_len);
    skb_reset_network_header(skb);
    skb_reset_transport_header(skb);

    if (virtio_legacy_is_needed(q)) {
        virt_hdr.hdr.flags = 0;
        virt_hdr.hdr.gso_type = VIRTIO_NET_HDR_GSO_NONE;
        virt_hdr.hdr.csum_start = 0;
        virt_hdr.hdr.csum_offset = 0;
        virt_hdr.hdr.hdr_length = sizeof(virtio_net_hdr_v1);

        memcpy(skb->cb, &virt_hdr, sizeof(virt_hdr));
    }

    if (q->vlan) {
        skb->vlan_tci = htons(q->vlan);
        skb->pkt_type = PACKET_VLAN;
    }

    ret = dev_queue_xmit(skb);
    if (ret < 0) {
        kfree_skb(skb);
    }

    return ret;
}

ssize_t macvtap_receive(struct macvtap_queue *q, struct msghdr *m,
                        const struct iovec *iv, unsigned long total_len,
                        size_t count, int noblock) {
    struct sk_buff *skb;
    struct virtio_net_hdr *hdr = NULL;
    int err;
    size_t len = 0;
    size_t i;

    if (!q || !m || !iv || !total_len)
        return -EINVAL;

    if (q->vnet_hdr) {
        if (total_len < sizeof(*hdr))
            return -EINVAL;

        if (memcpy_from_msg(hdr, m, sizeof(*hdr)) < 0)
            return -EFAULT;

        if (hdr->gso_type || hdr->csum_start || hdr->csum_offset ||
            hdr->flags & VIRTIO_NET_HDR_F_NEEDS_CSUM) {
            return -EINVAL;
        }
    }

    skb = __skb_alloc(q->netdev->mtu + VLAN_HLEN, 0, GFP_KERNEL, 0);
    if (!skb)
        return -ENOMEM;

    for (i = 0; i < count && len < total_len; i++) {
        size_t n = min(total_len - len, iv[i].iov_len);
        err = skb_add_data(skb, iv[i].iov_base, n);
        if (err < 0) {
            kfree_skb(skb);
            return err;
        }
        len += n;
    }

    if (len != total_len) {
        kfree_skb(skb);
        return -EINVAL;
    }

    skb->protocol = eth_type_trans(skb, q->netdev);
    skb->dev = q->netdev;
    skb->pkt_type = PACKET_HOST;

    if (q->vnet_hdr) {
        skb_push(skb, sizeof(*hdr));
        memcpy(skb->data, hdr, sizeof(*hdr));
    }

    if (q->vlan) {
        skb = vlan_insert_tag(skb, htons(ETH_P_8021Q), q->vlan->vid);
        if (!skb)
            return -ENOMEM;
    }

    q->netdev->stats.rx_packets++;
    q->netdev->stats.rx_bytes += len;

    netif_rx(skb);

    return len;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock) {
    struct sk_buff *skb;
    struct virtio_net_hdr *hdr = NULL;
    size_t len = 0;
    ssize_t ret;
    int err = 0;
    size_t offset = 0;

    if (!q || !m || !iv || !total_len)
        return -EINVAL;

    if (q->vnet_hdr) {
        hdr = kmalloc(sizeof(*hdr), GFP_KERNEL);
        if (!hdr)
            return -ENOMEM;
    }

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb) {
        kfree(hdr);
        return -ENOMEM;
    }

    skb->data_len = total_len;
    skb->len = total_len;
    skb->truesize += total_len;
    atomic_add(skb->truesize, &q->stats.rx_bytes);

    while (len < total_len && offset < count) {
        void *buf = iov_iter_kvec((struct iov_iter *)m->msg_iter);
        if (!buf) {
            err = -EFAULT;
            break;
        }

        memcpy(skb->data + len, buf, min(total_len - len, (size_t)iov_iter_count((struct iov_iter *)m->msg_iter)));
        len += iov_iter_count((struct iov_iter *)m->msg_iter);
        offset++;
    }

    if (err) {
        kfree(hdr);
        kfree_skb(skb);
        return err;
    }

    if (q->vnet_hdr) {
        if (skb->len < sizeof(*hdr)) {
            kfree_skb(skb);
            kfree(hdr);
            return -EINVAL;
        }

        memcpy(skb_push(skb, sizeof(*hdr)), hdr, sizeof(*hdr));
        skb_reset_network_header(skb);
    }

    if (q->vlan) {
        skb->vlan_tci = htons(q->vlan);
        ret = dev_queue_xmit(skb);
    } else {
        ret = dev_queue_xmit(skb);
    }

    if (ret < 0) {
        atomic_long_inc(&q->stats.rx_errors);
        kfree(hdr);
        return ret;
    }

    kfree(hdr);
    return len;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock)
{
    ssize_t ret;
    struct sk_buff *skb;
    struct virtio_net_hdr *hdr = NULL;
    size_t len = total_len;
    int err;

    if (!q || !m || !iv || !total_len || count == 0)
        return -EINVAL;

    skb = alloc_skb(len + VLAN_HLEN, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (q->vnet_hdr_sz) {
        hdr = skb_put(skb, q->vnet_hdr_sz);
        memset(hdr, 0, q->vnet_hdr_sz);
    }

    ret = skb_copy_datagram_from_iovec(skb, 0, iv, 0, len);
    if (ret < 0)
        goto error_free_skb;

    if (q->vlan) {
        skb->vlan_tci = q->vlan;
        skb_set_protocol(skb, htons(ETH_P_8021Q));
    } else {
        skb_set_mac_header(skb, -ETH_HLEN);
    }

    skb->protocol = eth_type_trans(skb, q->dev);
    skb_reset_network_header(skb);

    err = dev_queue_xmit(skb);
    if (err < 0) {
        ret = err;
        goto error_free_skb;
    }

    return len;

error_free_skb:
    kfree_skb(skb);
    return ret;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock)
{
    ssize_t ret;
    struct sk_buff *skb;
    struct virtio_net_hdr *vhdr = NULL;
    size_t vhdr_len = 0;
    int err;

    if (q->vnet_hdr) {
        vhdr_len = sizeof(*vhdr);
        vhdr = kzalloc(vhdr_len, GFP_KERNEL);
        if (!vhdr)
            return -ENOMEM;
    }

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb) {
        ret = -ENOMEM;
        goto free_vhdr;
    }

    skb_set_owner_w(skb, q->vport->dev);

    if (q->vnet_hdr) {
        if (copy_from_iter(vhdr, vhdr_len, m->msg_iter) != vhdr_len) {
            ret = -EFAULT;
            goto free_skb;
        }
    }

    ret = skb_zerocopy(skb, iv, count, total_len);
    if (ret < 0)
        goto free_skb;

    if (q->vnet_hdr)
        virtio_net_hdr_to_skb(skb, vhdr, 0);

    if (q->vlgrp) {
        err = vlan_hwaccel_receive_skb(skb, q->vlgrp, q->vlan_id);
        if (err) {
            ret = err;
            goto free_skb;
        }
    } else {
        netif_receive_skb(skb);
    }

    return ret;

free_skb:
    kfree_skb(skb);
free_vhdr:
    kfree(vhdr);
    return ret;
}
